import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int T = sc.nextInt();

        for (int t = 0; t < T; t++) {
            int n = sc.nextInt();
            int[] arr = new int[n];

            // 读取数组
            for (int i = 0; i < n; i++) {
                arr[i] = sc.nextInt();
            }

            System.out.println(solve(arr));
        }
        sc.close();
    }

    public static long solve(int[] arr) {
        int n = arr.length;

        // 计算所有元素的绝对值之和
        long absSum = 0;
        for (int x : arr) {
            absSum += Math.abs((long)x);
        }

        // 找到绝对值最小的元素
        int minAbs = Math.abs(arr[0]);
        for (int x : arr) {
            minAbs = Math.min(minAbs, Math.abs(x));
        }

        // 统计负数的个数
        int negCount = 0;
        for (int x : arr) {
            if (x < 0) {
                negCount++;
            }
        }

        // 如果负数个数为偶数，所有数都可以为正
        // 如果负数个数为奇数，必须保留一个最小绝对值为负
        if (negCount % 2 == 0) {
            return absSum;
        } else {
            return absSum - 2 * (long)minAbs;
        }
    }
}
```

